// Bundles every module's SQL migrations into src/migrations/migrations.g.ts,
// so the Worker can apply them itself (see src/migrations/run-migrations.ts).
// Run after `pnpm db:generate` in any module:  pnpm --filter @igongo/api gen:migrations
// CI fails if the generated file is out of date.

import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { migrationFiles } from "./migration-order.mjs";

const root = fileURLToPath(new URL("../../..", import.meta.url));
const entries = migrationFiles(root).map((m) => {
  const sql = readFileSync(m.path, "utf8");
  return { module: m.module, name: m.name.replace(/\.sql$/, ""), checksum: createHash("sha256").update(sql).digest("hex").slice(0, 16), sql };
});
const body = [
  "// GENERATED by apps/api/scripts/gen-migrations.mjs from modules/*/migrations. Do not edit.",
  "// Every module's SQL migrations, in apply order.",
  "",
  'import type { Migration } from "./migration";',
  "",
  `export const MIGRATIONS: Migration[] = ${JSON.stringify(entries, null, 1)};`,
  "",
].join("\n");
writeFileSync(new URL("../src/migrations/migrations.g.ts", import.meta.url), body);
process.stdout.write(`${entries.length} migrations bundled\n`);
